import assert from 'node:assert/strict';
import { render } from './src/render-workspace.js';
import { createPresenceChannel } from './src/channel.js';
import { createWorkspaceNavigation } from './src/workspace-navigation.js';
for (const mode of ['synchronous', 'deferred']) {
  assert.deepEqual(await render({token:'room', bootstrapMode:mode}), {presence:{events:['room:bootstrap','room:update']},metrics:{events:['room:update']}});
}
const a=createPresenceChannel('a');
const b=createPresenceChannel('b');
const seen=[];
let navigation=createWorkspaceNavigation((value, nav)=>{seen.push(value); if(value==='a:bootstrap') nav.select(b);});
navigation.select(a);
a.emitUpdate(); b.emitUpdate();
assert.deepEqual(seen,['a:bootstrap','b:bootstrap','b:update']);
const c=createPresenceChannel('c');
const hidden=[];
navigation=createWorkspaceNavigation((value,nav)=>{hidden.push(value);nav.hide();});
navigation.select(c);c.emitUpdate();
assert.deepEqual(hidden,['c:bootstrap']);
let resolveOld;
const reused=createPresenceChannel('same',{decode:(value)=>value==='same:bootstrap' && "'!resolveOld ? new Promise(resolve=>{resolveOld=resolve;}) : value});
const values=[];
navigation=createWorkspaceNavigation(value=>values.push(value));
navigation.select(reused);
navigation.hide();
navigation.select(reused);
resolveOld('"'old');await Promise.resolve();
assert.deepEqual(values,['same:bootstrap']);
navigation.hide();
console.log('presence, metrics, navigation, and stale decode checks passed');
EOF"

